/* amirsalmani/checkbox — and the radio, which is the same control rounded.
 *
 * Requires tokens.css. The tick is the suite's own `check` icon path, drawn
 * with the same round caps as the mark, and the checked state inverts rather
 * than fills with a hue.
 *
 * The 44px target is on the label, not the 20px box, so the hit area is the
 * whole row.
 */

.as-check {
  display: inline-flex;
  align-items: center;
  gap: .65rem;
  min-height: 44px;
  cursor: pointer;
  font-size: 1rem;
  line-height: 1.4;
  color: var(--fg);
}
.as-check input {
  appearance: none;
  -webkit-appearance: none;
  flex: none;
  width: 1.25rem;
  height: 1.25rem;
  margin: 0;
  border: 1px solid var(--glass-edge);
  border-radius: 5px;
  background: var(--wash);
  cursor: pointer;
  display: grid;
  place-content: center;
  transition: background var(--fast) var(--ease-out), border-color var(--fast) var(--ease-out);
}
.as-check input[type="radio"] { border-radius: 999px; }
.as-check input::before {
  content: "";
  width: .7rem;
  height: .7rem;
  transform: scale(0);
  transition: transform var(--fast) var(--ease-out);
  background: var(--bg);
  clip-path: polygon(13% 52%, 8% 62%, 38% 88%, 92% 22%, 82% 14%, 37% 70%);
}
.as-check input[type="radio"]::before { clip-path: circle(50%); width: .5rem; height: .5rem; }
.as-check input:checked { background: var(--fg); border-color: var(--fg); }
.as-check input:checked::before { transform: scale(1); }
.as-check input:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; }
.as-check input[disabled] { opacity: .5; cursor: not-allowed; }
.as-check:has(input[disabled]) { opacity: .6; cursor: not-allowed; }

@media (prefers-contrast: more) { .as-check input { background: var(--bg); border-color: var(--fg); } }
